"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["80013"],{72417(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.valor_categorico_conta_como_aprovacao_obrigatoria","status":422,"titulo":"\xc9 obrigat\xf3rio informar se o valor categ\xf3rico conta como aprova\xe7\xe3o"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.valor_categorico_conta_como_aprovacao_obrigatoria","requisitos":[],"oQueAconteceu":["Um item de `valores`, na cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) de um tipo categ\xf3rico, n\xe3o traz `contaComoAprovacao`, ou traz `null`. A aprova\xe7\xe3o \xe9 a decis\xe3o que o valor carrega: ela diz se escolher aquele valor conta como aprova\xe7\xe3o na etapa. Por isso o sistema n\xe3o a presume, e o valor `false` precisa ser dito, n\xe3o omitido.","A recusa vem na lista `errors` da resposta, com `field` igual a `valores[i].contaComoAprovacao`, em que `i` \xe9 a posi\xe7\xe3o do item, contada a partir de 0. Cada item com problema gera a pr\xf3pria entrada, junto das recusas de [c\xf3digo](/erros/uniplus.configuracao.tipo_conceito.valor_categorico_codigo_invalido) e de [r\xf3tulo](/erros/uniplus.configuracao.tipo_conceito.valor_categorico_rotulo_invalido) do mesmo item, e nada \xe9 gravado. A recusa s\xf3 aparece em tipo de natureza `categorico`.","Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Informe `contaComoAprovacao` como `true` ou `false` no item indicado em `field`, por exemplo `{ \\"codigo\\": \\"APTO\\", \\"rotulo\\": \\"Apto\\", \\"contaComoAprovacao\\": true }`, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);